package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var mod int64 = 998244353

func pw(a, b int64) int64 {
	c := b
	d := a
	res := int64(1)
	for c > 0 {
		if c&1 != 0 {
			res *= d
			res %= mod
		}
		d *= d
		d %= mod
		c /= 2
	}
	return res
}

func inv(a int64) int64 {
	return pw(a, mod-2)
}

var reader *bufio.Reader

func readln() string {
	line, _ := reader.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
}

func readstrings() []string {
	return strings.Split(readln(), " ")
}

func readints() []int {
	strs := readstrings()
	res := make([]int, len(strs))
	for i, s := range strs {
		res[i], _ = strconv.Atoi(s)
	}
	return res
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	f := make([]int64, 500010)
	for i := range f {
		f[i] = 1
	}
	for i := 2; i <= 500000; i++ {
		f[i] = f[i-1] * int64(i) % mod
	}

	tt := 1
	for tt > 0 {
		tt--
		nk := readints()
		n := nk[0]
		k := nk[1]
		var ans int64 = 0
		for i := 1; i <= n-k+1; i++ {
			cnt := n / i
			if cnt < k {
				continue
			}
			sum := f[cnt-1] * inv(f[k-1]) % mod
			sum = inv(f[cnt-k]) * sum % mod
			ans += sum
			ans %= mod
		}
		fmt.Fprintln(writer, ans)
	}
}
